.88a1 1 0 0 0-1.42-1.42m8.58-12.08a4.49 4.49 0 0 0-6.33 0l-3.89 3.88a1 1 0 1 0 1.42 1.42l3.88-3.88a2.52 2.52 0 0 1 3.5 0 2.47 2.47 0 0 1 0 3.5l-3.88 3.88a1 1 0 0 0 0 1.42 1 1 0 0 0 1.42 0l3.88-3.89a4.49 4.49 0 0 0 0-6.33M8.83 15.17a1 1 0 0 0 .71.29 1 1 0 0 0 .71-.29l4.92-4.92a1 1 0 1 0-1.42-1.42l-4.92 4.92a1 1 0 0 0 0 1.42"/></svg></span><span class="sr-only" data-pagefind-ignore="">Section titled “父节点给约束，子节点报尺寸”</span></a></div><p>Snapshot 采用与 Flutter 相同的 Box 布局协议：父节点向子节点传递 <code>BoxConstraints</code>，子节点必须在范围内选择尺寸，父节点再决定子节点的位置。</p><div class="expressive-code"><link rel="stylesheet" href="/_astro/ec.w36nc.css"><script data-cfasync="false" type="module" src="/_astro/ec.0vx5m.js"></script><figure class="frame not-content"><figcaption class="header"></figcaption><pre data-language="kotlin"><code><div class="ec-line"><div class="code"><span style="--0:#C792EA;--1:#8844AE">data</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#C792EA;--1:#8844AE">class</span><span style="--0:#D6DEEB;--1:#403F53"> BoxConstraints(</span></div></div><div class="ec-line"><div class="code"><span class="indent">    </span><span style="--0:#C792EA;--1:#8844AE">val</span><span style="--0:#D6DEEB;--1:#403F53"> minWidth: Float </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">0f</span><span style="--0:#D6DEEB;--1:#403F53">,</span></div></div><div class="ec-line"><div class="code"><span class="indent">    </span><span style="--0:#C792EA;--1:#8844AE">val</span><span style="--0:#D6DEEB;--1:#403F53"> maxWidth: Float </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> Float.POSITIVE_INFINITY,</span></div></div><div class="ec-line"><div class="code"><span class="indent">    </span><span style="--0:#C792EA;--1:#8844AE">val</span><span style="--0:#D6DEEB;--1:#403F53"> minHeight: Float </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">0f</span><span style="--0:#D6DEEB;--1:#403F53">,</span></div></div><div class="ec-line"><div class="code"><span class="indent">    </span><span style="--0:#C792EA;--1:#8844AE">val</span><span style="--0:#D6DEEB;--1:#403F53"> maxHeight: Float </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> Float.POSITIVE_INFINITY,</span></div></div><div class="ec-line"><div class="code"><span style="--0:#D6DEEB;--1:#403F53">)</span></div></div></code></pre><div class="copy"><div aria-live="polite"></div><button title="复制到剪贴板" data-copied="复制成功！" data-code="data class BoxConstraints(    val minWidth: Float = 0f,    val maxWidth: Float = Float.POSITIVE_INFINITY,    val minHeight: Float = 0f,    val maxHeight: Float = Float.POSITIVE_INFINITY,)"><div></div></button></div></figure></div><p>常用工厂：</p><table><thead><tr><th>工厂</th><th>结果</th></tr></thead><tbody><tr><td><code>tight(size)</code></td><td>宽高都固定</td></tr><tr><td><code>tightFor(width, height)</code></td><td>只固定指定的维度</td></tr><tr><td><code>loose(size)</code></td><td>最小为 0，最大为给定尺寸</td></tr><tr><td><code>expand(width, height)</code></td><td>尽可能扩张，未指定维度默认为无限</td></tr></tbody></table><div class="sl-heading-wrapper level-h2"><h2 id="container-的组合顺序" __collectHeading="true">Container 的组合顺序</h2><a class="sl-anchor-link" href="#container-的组合顺序"><span aria-hidden="true" class="sl-anchor-icon"><svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="m12.11 15.39-3.88 3.88a2.52 2.52 0 0 1-3.5 0 2.47 2.47 0 0 1 0-3.5l3.88-3.88a1 1 0 1 0-1.42-1.42l-3.88 3.89a4.48 4.48 0 0 0 6.33 6.33l3.89-3.88a1 1 0 0 0-1.42-1.42m8.58-12.08a4.49 4.49 0 0 0-6.33 0l-3.89 3.88a1 1 0 1 0 1.42 1.42l3.88-3.88a2.52 2.52 0 0 1 3.5 0 2.47 2.47 0 0 1 0 3.5l-3.88 3.88a1 1 0 0 0 0 1.42 1 1 0 0 0 1.42 0l3.88-3.89a4.49 4.49 0 0 0 0-6.33M8.83 15.17a1 1 0 0 0 .71.29 1 1 0 0 0 .71-.29l4.92-4.92a1 1 0 1 0-1.42-1.42l-4.92 4.92a1 1 0 0 0 0 1.42"/></svg></span><span class="sr-only" data-pagefind-ignore="">Section titled “Container 的组合顺序”</span></a></div><p><code>Container</code> 不是单一 RenderBox，而是按属性组合多个 Widget。大致顺序为：子节点 → 对齐 → padding → 颜色/裁剪/装饰 → 约束 → margin → transform。</p><p>这带来几个重要规则：</p><ul><li><code>width</code> / <code>height</code> 会收紧 <code>constraints</code>；</li><li><code>margin</code> 实际是最外层 Padding；</li><li><code>color</code> 与 <code>decoration</code> 不能同时传入；需要同时使用时把颜色放进 <code>BoxDecoration</code>；</li><li><code>clipBehavior != NONE</code> 时必须提供可生成裁剪路径的 <code>decoration</code>；</li><li>没有子节点、没有约束的空 Container 在无界根约束下会收缩为零尺寸；根出图仍需非零宽高。</li></ul><div class="sl-heading-wrapper level-h2"><h2 id="flex-布局" __collectHeading="true">Flex 布局</h2><a class="sl-anchor-link" href="#flex-布局"><span aria-hidden="true" class="sl-anchor-icon"><svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="m12.11 15.39-3.88 3.88a2.52 2.52 0 0 1-3.5 0 2.47 2.47 0 0 1 0-3.5l3.88-3.88a1 1 0 1 0-1.42-1.42l-3.88 3.89a4.48 4.48 0 0 0 6.33 6.33l3.89-3.88a1 1 0 0 0-1.42-1.42m8.58-12.08a4.49 4.49 0 0 0-6.33 0l-3.89 3.88a1 1 0 1 0 1.42 1.42l3.88-3.88a2.52 2.52 0 0 1 3.5 0 2.47 2.47 0 0 1 0 3.5l-3.88 3.88a1 1 0 0 0 0 1.42 1 1 0 0 0 1.42 0l3.88-3.89a4.49 4.49 0 0 0 0-6.33M8.83 15.17a1 1 0 0 0 .71.29 1 1 0 0 0 .71-.29l4.92-4.92a1 1 0 1 0-1.42-1.42l-4.92 4.92a1 1 0 0 0 0 1.42"/></svg></span><span class="sr-only" data-pagefind-ignore="">Section titled “Flex 布局”</span></a></div><p><code>Row</code> 与 <code>Column</code> 都是 <code>Flex</code> 的特化：</p><table><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>mainAxisAlignment</code></td><td>子节点在主轴上的分布方式</td></tr><tr><td><code>mainAxisSize</code></td><td>Flex 自身在主轴上取最大或最小尺寸</td></tr><tr><td><code>crossAxisAlignment</code></td><td>子节点在交叉轴上的对齐方式</td></tr><tr><td><code>textDirection</code></td><td>水平方向的 start/end 解释</td></tr><tr><td><code>verticalDirection</code></td><td>垂直方向排列顺序</td></tr><tr><td><code>textBaseline</code></td><td>基线对齐时使用的基线类型</td></tr><tr><td><code>clipBehavior</code></td><td>溢出时的裁剪策略</td></tr></tbody></table><p><code>Expanded</code> 相当于 <code>Flexible(fit = TIGHT)</code>，强制占满分配到的空间；<code>Flexible(fit = LOOSE)</code> 允许子节点更小。两者只能是 Flex 的直接子节点。</p><div class="expressive-code"><figure class="frame not-content"><figcaption class="header"></figcaption><pre data-language="kotlin"><code><div class="ec-line"><div class="code"><span style="--0:#82AAFF;--1:#3B61B0">SizedBox</span><span style="--0:#D6DEEB;--1:#403F53">(width </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">600f</span><span style="--0:#D6DEEB;--1:#403F53">, height </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">160f</span><span style="--0:#D6DEEB;--1:#403F53">) {</span></div></div><div class="ec-line"><div class="code"><span class="indent">    </span><span style="--0:#82AAFF;--1:#3B61B0">Row</span><span style="--0:#D6DEEB;--1:#403F53">(crossAxisAlignment </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> CrossAxisAlignment.STRETCH) {</span></div></div><div class="ec-line"><div class="code"><span class="indent">        </span><span style="--0:#82AAFF;--1:#3B61B0">Expanded</span><span style="--0:#D6DEEB;--1:#403F53">(flex </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">2</span><span style="--0:#D6DEEB;--1:#403F53">) { </span><span style="--0:#82AAFF;--1:#3B61B0">Container</span><span style="--0:#D6DEEB;--1:#403F53">(color </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">0xFF38BDF8</span><span style="--0:#D6DEEB;--1:#403F53">.</span><span style="--0:#82AAFF;--1:#3B61B0">toInt</span><span style="--0:#D6DEEB;--1:#403F53">()) }</span></div></div><div class="ec-line"><div class="code"><span class="indent">        </span><span style="--0:#82AAFF;--1:#3B61B0">Flexible</span><span style="--0:#D6DEEB;--1:#403F53">(flex </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">1</span><span style="--0:#D6DEEB;--1:#403F53">) { </span><span style="--0:#82AAFF;--1:#3B61B0">Container</span><span style="--0:#D6DEEB;--1:#403F53">(width </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">120f</span><span style="--0:#D6DEEB;--1:#403F53">, color </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">0xFFA78BFA</span><span style="--0:#D6DEEB;--1:#403F53">.</span><span style="--0:#82AAFF;--1:#3B61B0">toInt</span><span style="--0:#D6DEEB;--1:#403F53">()) }</span></div></div><div class="ec-line"><div class="code"><span class="indent"><span style="--0:#D6DEEB;--1:#403F53">    </span></span><span style="--0:#D6DEEB;--1:#403F53">}</span></div></div><div class="ec-line"><div class="code"><span style="--0:#D6DEEB;--1:#403F53">}</span></div></div></code></pre><div class="copy"><div aria-live="polite"></div><button title="复制到剪贴板" data-copied="复制成功！" data-code="SizedBox(width = 600f, height = 160f) {    Row(crossAxisAlignment = CrossAxisAlignment.STRETCH) {        Expanded(flex = 2) { Container(color = 0xFF38BDF8.toInt()) }        Flexible(flex = 1) { Container(width = 120f, color = 0xFFA78BFA.toInt()) }    }}"><div></div></button></div></figure></div><aside aria-label="Flex 子项需要有限的主轴空间" class="starlight-aside starlight-aside--caution"><p class="starlight-aside__title" aria-hidden="true"><svg aria-hidden="true" class="starlight-aside__icon astro-tynuvajn" width="16" height="16" viewBox="0 0 24 24" fill="currentColor" style="--sl-icon-size: 1em;"><path d="M12 16a1 1 0 1 0 0 2 1 1 0 0 0 0-2Zm10.67 1.47-8.05-14a3 3 0 0 0-5.24 0l-8 14A3 3 0 0 0 3.94 22h16.12a3 3 0 0 0 2.61-4.53Zm-1.73 2a1 1 0 0 1-.88.51H3.94a1 1 0 0 1-.88-.51 1 1 0 0 1 0-1l8-14a1 1 0 0 1 1.78 0l8.05 14a1 1 0 0 1 .05 1.02v-.02ZM12 8a1 1 0 0 0-1 1v4a1 1 0 0 0 2 0V9a1 1 0 0 0-1-1Z"/></svg>Flex 子项需要有限的主轴空间</p><div class="starlight-aside__content"><p>当 Flex 主轴约束无限时，无法计算可分配的“剩余空间”。请先通过外层 <code>SizedBox</code>、<code>Container</code> 或 <code>ConstrainedBox</code> 提供有限主轴尺寸，再使用 <code>Expanded</code> 或紧约束的 <code>Flexible</code>。</p></div></aside><div class="sl-heading-wrapper level-h2"><h2 id="stack-与-positioned" __collectHeading="true">Stack 与 Positioned</h2><a class="sl-anchor-link" href="#stack-与-positioned"><span aria-hidden="true" class="sl-anchor-icon"><svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="m12.11 15.39-3.88 3.88a2.52 2.52 0 0 1-3.5 0 2.47 2.47 0 0 1 0-3.5l3.88-3.88a1 1 0 1 0-1.42-1.42l-3.88 3.89a4.48 4.48 0 0 0 6.33 6.33l3.89-3.88a1 1 0 0 0-1.42-1.42m8.58-12.08a4.49 4.49 0 0 0-6.33 0l-3.89 3.88a1 1 0 1 0 1.42 1.42l3.88-3.88a2.52 2.52 0 0 1 3.5 0 2.47 2.47 0 0 1 0 3.5l-3.88 3.88a1 1 0 0 0 0 1.42 1 1 0 0 0 1.42 0l3.88-3.89a4.49 4.49 0 0 0 0-6.33M8.83 15.17a1 1 0 0 0 .71.29 1 1 0 0 0 .71-.29l4.92-4.92a1 1 0 1 0-1.42-1.42l-4.92 4.92a1 1 0 0 0 0 1.42"/></svg></span><span class="sr-only" data-pagefind-ignore="">Section titled “Stack 与 Positioned”</span></a></div><p><code>Stack</code> 先布局非 Positioned 子节点，再按 <code>left</code> / <code>top</code> / <code>right</code> / <code>bottom</code> / <code>width</code> / <code>height</code> 放置 Positioned 子节点。</p><div class="expressive-code"><figure class="frame not-content"><figcaption class="header"></figcaption><pre data-language="kotlin"><code><div class="ec-line"><div class="code"><span style="--0:#82AAFF;--1:#3B61B0">Stack</span><span style="--0:#D6DEEB;--1:#403F53">(</span></div></div><div class="ec-line"><div class="code"><span class="indent"><span style="--0:#D6DEEB;--1:#403F53">    </span></span><span style="--0:#D6DEEB;--1:#403F53">alignment </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> BoxAlignment.CENTER,</span></div></div><div class="ec-line"><div class="code"><span class="indent"><span style="--0:#D6DEEB;--1:#403F53">    </span></span><span style="--0:#D6DEEB;--1:#403F53">fit </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> StackFit.LOOSE,</span></div></div><div class="ec-line"><div class="code"><span class="indent"><span style="--0:#D6DEEB;--1:#403F53">    </span></span><span style="--0:#D6DEEB;--1:#403F53">clipBehavior </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> ClipBehavior.NONE,</span></div></div><div class="ec-line"><div class="code"><span style="--0:#D6DEEB;--1:#403F53">) {</span></div></div><div class="ec-line"><div class="code"><span class="indent">    </span><span style="--0:#82AAFF;--1:#3B61B0">Container</span><span style="--0:#D6DEEB;--1:#403F53">(width </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">400f</span><span style="--0:#D6DEEB;--1:#403F53">, height </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">240f</span><span style="--0:#D6DEEB;--1:#403F53">)</span></div></div><div class="ec-line"><div class="code"><span class="indent">    </span><span style="--0:#82AAFF;--1:#3B61B0">Positioned</span><span style="--0:#D6DEEB;--1:#403F53">(right </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">16f</span><span style="--0:#D6DEEB;--1:#403F53">, bottom </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">16f</span><span style="--0:#D6DEEB;--1:#403F53">) {</span></div></div><div class="ec-line"><div class="code"><span class="indent">        </span><span style="--0:#82AAFF;--1:#3B61B0">Container</span><span style="--0:#D6DEEB;--1:#403F53">(width </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">80f</span><span style="--0:#D6DEEB;--1:#403F53">, height </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">32f</span><span style="--0:#D6DEEB;--1:#403F53">)</span></div></div><div class="ec-line"><div class="code"><span class="indent"><span style="--0:#D6DEEB;--1:#403F53">    </span></span><span style="--0:#D6DEEB;--1:#403F53">}</span></div></div><div class="ec-line"><div class="code"><span style="--0:#D6DEEB;--1:#403F53">}</span></div></div></code></pre><div class="copy"><div aria-live="polite"></div><button title="复制到剪贴板" data-copied="复制成功！" data-code="Stack(    alignment = BoxAlignment.CENTER,    fit = StackFit.LOOSE,    clipBehavior = ClipBehavior.NONE,) {    Container(width = 400f, height = 240f)    Positioned(right = 16f, bottom = 16f) {        Container(width = 80f, height = 32f)    }}"><div></div></button></div></figure></div><p>同一轴上 <code>left</code>、<code>right</code>、<code>width</code> 最多只能给两个，垂直轴规则相同。</p><aside aria-label="Stack 默认会裁剪" class="starlight-aside starlight-aside--note"><p class="starlight-aside__title" aria-hidden="true"><svg aria-hidden="true" class="starlight-aside__icon astro-tynuvajn" width="16" height="16" viewBox="0 0 24 24" fill="currentColor" style="--sl-icon-size: 1em;"><path d="M12 11a1 1 0 0 0-1 1v4a1 1 0 0 0 2 0v-4a1 1 0 0 0-1-1Zm.38-3.92a1 1 0 0 0-.76 0 1 1 0 0 0-.33.21 1.15 1.15 0 0 0-.21.33 1 1 0 0 0 .21 1.09c.097.088.209.16.33.21A1 1 0 0 0 13 8a1.05 1.05 0 0 0-.29-.71 1 1 0 0 0-.33-.21ZM12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm0 18a8 8 0 1 1 0-16.001A8 8 0 0 1 12 20Z"/></svg>Stack 默认会裁剪</p><div class="starlight-aside__content"><p><code>Stack</code> 默认使用 <code>HARD_EDGE</code>。阴影或装饰需要绘制到边界之外时，应显式设置 <code>clipBehavior = ClipBehavior.NONE</code>。</p></div></aside><div class="sl-heading-wrapper level-h2"><h2 id="溢出相关-widget" __collectHeading="true">溢出相关 Widget</h2><a class="sl-anchor-link" href="#溢出相关-widget"><span aria-hidden="true" class="sl-anchor-icon"><svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="m12.11 15.39-3.88 3.88a2.52 2.52 0 0 1-3.5 0 2.47 2.47 0 0 1 0-3.5l3.88-3.88a1 1 0 1 0-1.42-1.42l-3.88 3.89a4.48 4.48 0 0 0 6.33 6.33l3.89-3.88a1 1 0 0 0-1.42-1.42m8.58-12.08a4.49 4.49 0 0 0-6.33 0l-3.89 3.88a1 1 0 1 0 1.42 1.42l3.88-3.88a2.52 2.52 0 0 1 3.5 0 2.47 2.47 0 0 1 0 3.5l-3.88 3.88a1 1 0 0 0 0 1.42 1 1 0 0 0 1.42 0l3.88-3.89a4.49 4.49 0 0 0 0-6.33M8.83 15.17a1 1 0 0 0 .71.29 1 1 0 0 0 .71-.29l4.92-4.92a1 1 0 1 0-1.42-1.42l-4.92 4.92a1 1 0 0 0 0 1.42"/></svg></span><span class="sr-only" data-pagefind-ignore="">Section titled “溢出相关 Widget”</span></a></div><p><code>AspectRatio</code> 用有限宽高比确定尺寸，父约束至少一轴有界；<code>FractionallySizedBox</code> 按父约束最大宽高的倍数设置子节点尺寸，设置比例的轴必须有界。<code>UnconstrainedBox</code> 可以解除传给子节点的轴约束，但自身仍遵守父约束。<code>Spacer</code> 可作为 Flex 的直属子项填满剩余空间。<code>IndexedStack</code> 会布局全部子项，只绘制指定索引。</p><table><thead><tr><th>Widget</th><th>行为</th></tr></thead><tbody><tr><td><code>OverflowBox</code></td><td>给子节点一套不同的约束，允许子节点超出父盒</td></tr><tr><td><code>SizedOverflowBox</code></td><td>自身使用指定尺寸，子节点仍按父约束布局</td></tr><tr><td><code>LimitedBox</code></td><td>仅在收到无限约束时施加最大宽高</td></tr><tr><td><code>ClipRect</code> / <code>ClipRRect</code> / <code>ClipOval</code> / <code>ClipPath</code></td><td>显式裁剪绘制结果</td></tr></tbody></table><p>布局溢出和绘制裁剪是两个不同问题：子节点可以布局得更大，但最终是否显示取决于父级和裁剪 Widget。</p><div class="sl-heading-wrapper level-h2"><h2 id="布局自省" __collectHeading="true">布局自省</h2><a class="sl-anchor-link" href="#布局自省"><span aria-hidden="true" class="sl-anchor-icon"><svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="m12.11 15.39-3.88 3.88a2.52 2.52 0 0 1-3.5 0 2.47 2.47 0 0 1 0-3.5l3.88-3.88a1 1 0 1 0-1.42-1.42l-3.88 3.89a4.48 4.48 0 0 0 6.33 6.33l3.89-3.88a1 1 0 0 0-1.42-1.42m8.58-12.08a4.49 4.49 0 0 0-6.33 0l-3.89 3.88a1 1 0 1 0 1.42 1.42l3.88-3.88a2.52 2.52 0 0 1 3.5 0 2.47 2.47 0 0 1 0 3.5l-3.88 3.88a1 1 0 0 0 0 1.42 1 1 0 0 0 1.42 0l3.88-3.89a4.49 4.49 0 0 0 0-6.33M8.83 15.17a1 1 0 0 0 .71.29 1 1 0 0 0 .71-.29l4.92-4.92a1 1 0 1 0-1.42-1.42l-4.92 4.92a1 1 0 0 0 0 1.42"/></svg></span><span class="sr-only" data-pagefind-ignore="">Section titled “布局自省”</span></a></div><div class="expressive-code"><figure class="frame not-content"><figcaption class="header"></figcaption><pre data-language="kotlin"><code><div class="ec-line"><div class="code"><span style="--0:#C792EA;--1:#8844AE">val</span><span style="--0:#D6DEEB;--1:#403F53"> root </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#82AAFF;--1:#3B61B0">layoutWidget</span><span style="--0:#D6DEEB;--1:#403F53"> {</span></div></div><div class="ec-line"><div class="code"><span class="indent">    </span><span style="--0:#82AAFF;--1:#3B61B0">Container</span><span style="--0:#D6DEEB;--1:#403F53">(width </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">320f</span><span style="--0:#D6DEEB;--1:#403F53">, height </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> </span><span style="--0:#F78C6C;--1:#AA0982">180f</span><span style="--0:#D6DEEB;--1:#403F53">) { </span><span style="--0:#919F9F;--1:#5F636F">/* ... */</span><span style="--0:#D6DEEB;--1:#403F53"> }</span></div></div><div class="ec-line"><div class="code"><span style="--0:#D6DEEB;--1:#403F53">}</span></div></div><div class="ec-line"><div class="code"><span style="--0:#C792EA;--1:#8844AE">val</span><span style="--0:#D6DEEB;--1:#403F53"> tree: LayoutNode </span><span style="--0:#C792EA;--1:#8844AE">=</span><span style="--0:#D6DEEB;--1:#403F53"> root.</span><span style="--0:#82AAFF;--1:#3B61B0">toLayoutNode</span><span style="--0:#D6DEEB;--1:#403F53">()</span></div></div></code></pre><div class="copy"><div aria-live="polite"></div><button title="复制到剪贴板" data-copied="复制成功！" data-code="val root = layoutWidget {    Container(width = 320f, height = 180f) { /* ... */ }}val tree: LayoutNode = root.toLayoutNode()"><div></div></button></div></figure></div><p><code>LayoutNode</code> 是只读快照，包含 RenderBox 类型、尺寸、局部偏移、全局偏移和子节点。它适合打印调试信息或写结构断言，不需要先生成 PNG。</p><p>定位问题时建议按顺序检查：根约束是否有限 → 子节点尺寸是否满足约束 → parentData 是否放在正确父节点下 → 是否被裁剪 → 是否只是绘制透明。</p></article></div><footer class="sl-flex astro-lyrtiueh"><div class="meta sl-flex astro-lyrtiueh"></div><div class="pagination-links print:hidden astro-6i6fca44" dir="ltr"><a href="/guides/concepts/" rel="prev" class="astro-6i6fca44"><svg aria-hidden="true" class="astro-6i6fca44 astro-tynuvajn" width="16" height="16" viewBox="0 0 24 24" fill="currentColor" style="--sl-icon-size: 1.5rem;"><path d="M17 11H9.41l3.3-3.29a1.004 1.004 0 1 0-1.42-1.42l-5 5a1 1 0 0 0-.21.33 1 1 0 0 0 0 .76 1 1 0 0 0 .21.33l5 5a1.002 1.002 0 0 0 1.639-.325 1 1 0 0 0-.219-1.095L9.41 13H17a1 1 0 0 0 0-2Z"/></svg><span class="astro-6i6fca44">上一页<br class="astro-6i6fca44"><span class="link-title astro-6i6fca44">核心概念</span></span></a><a href="/guides/widgets/" rel="next" class="astro-6i6fca44"><svg aria-hidden="true" class="astro-6i6fca44 astro-tynuvajn" width="16" height="16" viewBox="0 0 24 24" fill="currentColor" style="--sl-icon-size: 1.5rem;"><path d="M17.92 11.62a1.001 1.001 0 0 0-.21-.33l-5-5a1.003 1.003 0 1 0-1.42 1.42l3.3 3.29H7a1 1 0 0 0 0 2h7.59l-3.3 3.29a1.002 1.002 0 0 0 .325 1.639 1 1 0 0 0 1.095-.219l5-5a1 1 0 0 0 .21-.33 1 1 0 0 0 0-.76Z"/></svg><span class="astro-6i6fca44">下一页<br class="astro-6i6fca44"><span class="link-title astro-6i6fca44">Widget 与布局</span></span></a></div></footer></div></div></main></div></div></div></div><script>(function(){function c(){var b=a.contentDocument||(a.contentWindow&&a.contentWindow.document)