+<!DOCTYPE html><html lang="zh-CN" dir="ltr" data-theme="dark" data-has-toc data-has-sidebar class="astro-7jrn6cqt"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width, initial-scale=1"/><title>绘制、装饰与效果 | Snapshot</title><link rel="canonical" href="https://snapshot.muedsa.com/guides/painting/"/><link rel="sitemap" href="/sitemap-index.xml"/><link rel="shortcut icon" href="/logo_mark_mono.png" type="image/png"/><meta name="generator" content="Astro v7.3.3"/><meta name="generator" content="Starlight v0.42.2"/><meta property="og:title" content="绘制、装饰与效果"/><meta property="og:type" content="article"/><meta property="og:url" content="https://snapshot.muedsa.com/guides/painting/"/><meta property="og:locale" content="zh-CN"/><meta property="og:description" content="BoxDecoration、渐变、阴影、裁剪、透明度和滤镜。"/><meta property="og:site_name" content="Snapshot"/><meta name="twitter:card" content="summary_large_image"/><meta name="description" content="BoxDecoration、渐变、阴影、裁剪、透明度和滤镜。"/><!--
+  Starlight 在服务端输出时默认把页面标记为深色，再由客户端脚本读取主题。
+  这里在主题确定前隐藏正文，并让空白底色跟随系统主题，避免首屏出现深色闪烁。
+--><style>
+  html:not([data-theme-ready]) {
+    color-scheme: light dark;
+    background-color: Canvas;
+  }
+
+  html:not([data-theme-ready]) body {
+    visibility: hidden;
+  }
+</style><script data-cfasync="false">
+  window.StarlightThemeProvider = (() => {
+    let storedTheme = null;
+
+    try {
+      storedTheme = localStorage.getItem('starlight-theme');
+    } catch {
+      // 浏览器禁用存储时，继续使用系统主题。
+    }
+
+    const preferredTheme =
+      storedTheme === 'light' || storedTheme === 'dark'
+        ? storedTheme
+        : window.matchMedia('(prefers-color-scheme: light)').matches
+          ? 'light'
+          : 'dark';
+
+    document.documentElement.dataset.theme = preferredTheme;
+    document.documentElement.dataset.themeReady = '';
+
+    return {
+      updatePickers(theme = storedTheme || 'auto') {
+        document.querySelectorAll('starlight-theme-select').forEach((picker) => {
+          const select = picker.querySelector('select');
+          if (select) select.value = theme;
+
+          const template = document.querySelector('#theme-icons');
+          const newIcon = template?.content.querySelector(`.${theme}`);
+          if (!newIcon) return;
+
+          const oldIcon = picker.querySelector('svg.label-icon');
+          oldIcon?.replaceChildren(...newIcon.cloneNode(true).childNodes);
+        });
+      },
