def _lock(timeout=40.0):
    """Cross-process lock so parallel task workers cannot clobber suite-state.json."""
    os.makedirs(SUITE_TMP, exist_ok=True)
    path = os.path.join(SUITE_TMP, "suite-state.lock")
    deadline = time.time() + timeout
    while True:
        try:
            fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.close(fd)
            return path
        except FileExistsError:
            if time.time() > deadline:
                try:
                    os.remove(path)
                except OSError:
                    pass
                continue
            time.sleep(0.15)


def _unlock(path):
    try:
        os.remove(path)
    except OSError:
        pass


def mutate(fn):
    """Run fn(state) under the lock and persist the result."""
    lock = _lock()
    try:
        st = load()
        result = fn(st)
        save(st)
        return result
    finally:
        _unlock(lock)


